package com.shms.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="payments") public class Payment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="invoice_id",nullable=false) private Invoice invoice; @Column(nullable=false, precision=12, scale=2) private BigDecimal amount; @Enumerated(EnumType.STRING) @Column(name="payment_method") private PaymentMethod paymentMethod; @Column(name="transaction_reference") private String transactionReference; @Column(name="payment_date") private LocalDateTime paymentDate; @Enumerated(EnumType.STRING) private Status status=Status.PENDING; public enum PaymentMethod{CASH,CARD,BANK_TRANSFER,ONLINE} public enum Status{PENDING,COMPLETED,FAILED,REFUNDED} @PrePersist void pre(){if(paymentDate==null)paymentDate=LocalDateTime.now();} public Long getId(){return id;} public void setId(Long v){id=v;} public Invoice getInvoice(){return invoice;} public void setInvoice(Invoice v){invoice=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public PaymentMethod getPaymentMethod(){return paymentMethod;} public void setPaymentMethod(PaymentMethod v){paymentMethod=v;} public String getTransactionReference(){return transactionReference;} public void setTransactionReference(String v){transactionReference=v;} public LocalDateTime getPaymentDate(){return paymentDate;} public void setPaymentDate(LocalDateTime v){paymentDate=v;} public Status getStatus(){return status;} public void setStatus(Status v){status=v;} }
